"""Bundled assets, loaded as package data.

Read through importlib.resources rather than a path relative to the source tree,
so the icon still resolves once Ocura is packaged in P7 and there is no
repository around it. Bytes rather than a filename, so nothing depends on the
asset existing as a real file on disk.
"""

from __future__ import annotations

import logging
from importlib import resources

from PySide6.QtCore import Qt
from PySide6.QtGui import QIcon, QPixmap

logger = logging.getLogger(__name__)

ASSETS = "ocura.ui.assets"
APP_ICON = "ocura.png"
#: Generated by scripts/make_icon.py, and only used if the real icon is missing.
FALLBACK_ICON = "ocura.ico"

#: Windows asks for the icon at all of these; letting Qt downscale one large
#: source for each gives a smoother small icon than it picks on its own.
ICON_SIZES = (16, 20, 24, 32, 48, 64, 128, 256)


def _load(name: str) -> QPixmap | None:
    try:
        data = (resources.files(ASSETS) / name).read_bytes()
    except (FileNotFoundError, ModuleNotFoundError):
        return None
    pixmap = QPixmap()
    if not pixmap.loadFromData(data):
        return None
    return pixmap


def app_icon() -> QIcon:
    pixmap = _load(APP_ICON)
    if pixmap is None:
        logger.warning("%s missing from package data; falling back to %s", APP_ICON, FALLBACK_ICON)
        pixmap = _load(FALLBACK_ICON)
    if pixmap is None:
        logger.error("no application icon found in package data")
        return QIcon()

    icon = QIcon()
    for size in ICON_SIZES:
        icon.addPixmap(
            pixmap.scaled(
                size,
                size,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            )
        )
    return icon
